function profileFor(topic: string, category: string, subcategory: string): CommandProfile {
  const found = PROFILES[topic];
  if (found) return found;
  const safe = topic.toLowerCase().replace(/[^a-z0-9]+/g, "-");
  const base = topic.startsWith("kubectl") ? "kubectl" : topic.toLowerCase().includes("docker") ? "docker" : topic.toLowerCase().includes("terraform") ? "terraform" : topic.toLowerCase().includes("helm") ? "helm" : topic.toLowerCase().includes("argocd") ? "argocd" : topic.toLowerCase().includes("aws") || topic.toLowerCase().includes("cli") ? "aws" : safe;
  return {
    base, args:"--help", purpose:`Use ${topic} as part of the ${category} command workflow.`,
    when:`Use this command when working in ${subcategory}. Check the target environment and permissions before running commands that change state.`,
    flags:[{flag:"--help",meaning:"Show supported subcommands and options."},{flag:"--version",meaning:"Show installed tool version where supported."}],
    examples:[{label:"Show command help",command:`${base} --help`},{label:"Check installed version",command:`${base} --version`}],
    output:`Help text for ${topic}; available options depend on the installed tool version.`,
    next:[`${base} --help`,"Check the tool's current context and target environment."],
    task:`Open help for ${topic}, identify the read-only inspection option, and record the expected target environment.`,
    verify:"Confirm the command target, context, account/cluster and expected output before making changes."
  };
}

function slug(value: string) {
  return value.toLowerCase().normalize("NFKD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
}

export default function CommandExplorerWorkspace({
  mode,
  topic,
  category,
  subcategory,
}: {
  mode: "home" | "detail";
  topic?: string;
  category?: string;
  subcategory?: string;
}) {
  const categories = featureCatalog["command-explorer"].categories;
  const allTopics = useMemo(() => categories.flatMap((group) => group.subcategories.flatMap((sub) => sub.topics.map((name) => ({
    name, category:group.name, subcategory:sub.name,
    href:`/command-explorer/${slug(group.name)}/${slug(sub.name)}/${slug(name)}`
  })))), [categories]);
  const [search, setSearch] = useState("");
  const [favorites, setFavorites] = useState<string[]>([]);
  const [history, setHistory] = useState<string[]>([]);
  const [argument, setArgument] = useState("");
  const [selectedFlags, setSelectedFlags] = useState<string[]>([]);
  const [simCommand, setSimCommand] = useState("");
  const [simOutput, setSimOutput] = useState("");
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    try {
      setFavorites(JSON.parse(localStorage.getItem("devmavox-command-favorites") || "[]"));
      setHistory(JSON.parse(localStorage.getItem("devmavox-command-history") || "[]"));
    } catch { setFavorites([]); setHistory([]); }
  }, []);

  const matches = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return [];
    return allTopics.filter((item) => `${item.name} ${item.category} ${item.subcategory}`.toLowerCase().includes(q)).slice(0,18);
  }, [allTopics, search]);

  const selected = mode === "detail" && topic ? allTopics.find((item) => item.name === topic && item.category === category && item.subcategory === subcategory) : undefined;
  const profile = selected ? profileFor(selected.name, selected.category, selected.subcategory) : undefined;
  const currentArgument = argument || profile?.args || "";
  const commandPreview = profile ? [profile.base, currentArgument, ...selectedFlags].filter(Boolean).join(" ") : "";
  const saveHistory = (value: string) => {
    const next = [value, ...history.filter((item) => item !== value)].slice(0,12);
    setHistory(next);
    localStorage.setItem("devmavox-command-history", JSON.stringify(next));
  };
  const toggleFavorite = (value: string) => {
    const next = favorites.includes(value) ? favorites.filter((item) => item !== value) : [value, ...favorites];
    setFavorites(next);
    localStorage.setItem("devmavox-command-favorites", JSON.stringify(next));
  };
  const copyCommand = async (value: string) => {
    try {
      await navigator.clipboard.writeText(value);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1500);
      saveHistory(value);
    } catch { setCopied(false); }
  };
  const runSimulation = () => {
    const value = simCommand.trim();
    if (!value) { setSimOutput("Enter a command to run this safe, simulated practice check."); return; }
    const normalized = value.toLowerCase();
    const result = normalized.includes("kubectl get pods") ? "NAME          READY   STATUS    RESTARTS\napi-7d9f      1/1     Running   0\nworker-5c8    0/1     Pending   0\n\nSIMULATED OUTPUT — inspect the Pending Pod with kubectl describe." :
      normalized.includes("kubectl get nodes") ? "NAME       STATUS   ROLES    VERSION\nworker-1  Ready    <none>   v1.31.4\nworker-2  Ready    <none>   v1.31.4\n\nSIMULATED OUTPUT" :
      normalized.includes("docker ps") ? "CONTAINER ID   IMAGE       STATUS          NAMES\n9abc123       nginx:1.27  Up 12 minutes   web\n\nSIMULATED OUTPUT" :
      normalized.includes("docker logs") ? "2026-11-18T09:20:11Z INFO server started\n2026-11-18T09:21:02Z ERROR upstream connection refused\n\nSIMULATED OUTPUT" :
      normalized.startsWith("git status") ? "## feature/healthcheck\n M src/health.ts\n?? tests/health.test.ts\n\nSIMULATED OUTPUT" :
      normalized.startsWith("df ") || normalized === "df -h" ? "Filesystem      Size  Used Avail Use% Mounted on\n/dev/root       40G   31G  7G   82% /\n\nSIMULATED OUTPUT" :
      normalized.startsWith("free ") ? "               total        used        free\nMem:            15Gi         8Gi        2Gi\nSwap:          2.0Gi          0B      2.0Gi\n\nSIMULATED OUTPUT" :
      "Command accepted by the practice simulator. This is not a real shell and no host, cloud account, cluster or repository was changed. Use the command detail page for the expected output and verification steps.";
    setSimOutput(result);
    saveHistory(value);
  };

  if (mode === "home") {
    return (
      <main className="min-h-screen bg-[#060d18] px-4 py-8 text-slate-100 sm:px-6 lg:px-8">
        <div className="mx-auto max-w-7xl">
          <div className="mb-6 flex flex-wrap items-center justify-between gap-3">
            <Link href="/" className="text-sm text-slate-400 hover:text-white">← DevMavox Home</Link>
            <span className="rounded-full border border-emerald-500/30 bg-emerald-400/10 px-3 py-1 font-mono text-xs text-emerald-200">⌨ Command Terminal</span>
          </div>
          <header className="relative mb-7 overflow-hidden rounded-3xl border border-emerald-500/30 bg-gradient-to-br from-[#0b211b] via-[#101d2c] to-[#0b1220] p-6 sm:p-9">
            <div className="absolute -right-10 -top-16 h-64 w-64 rounded-full bg-emerald-400/10 blur-3xl"/>
            <p className="font-mono text-xs font-bold uppercase tracking-[.24em] text-emerald-300">DEVMAVOX · COMMAND WORKSPACE</p>
            <h1 className="mt-3 text-3xl font-black tracking-tight text-white sm:text-4xl">Command Explorer</h1>
            <p className="mt-3 max-w-3xl text-sm leading-7 text-slate-300">Search real DevOps commands, build command lines, copy practical examples and practise common diagnostic workflows.</p>
            <div className="mt-6 flex flex-wrap gap-2 text-xs text-emerald-100/80">
              <span className="rounded-lg border border-emerald-400/20 bg-black/20 px-3 py-2">11 command categories</span>
              <span className="rounded-lg border border-emerald-400/20 bg-black/20 px-3 py-2">{allTopics.length} command topics</span>
              <span className="rounded-lg border border-emerald-400/20 bg-black/20 px-3 py-2">Search · Build · Copy · Practise</span>
            </div>
          </header>

          <section className="mb-7 rounded-2xl border border-emerald-500/25 bg-[#081711] p-5">
            <label htmlFor="command-search" className="mb-2 block text-xs font-bold uppercase tracking-wider text-emerald-300">Search commands, tools or tasks</label>
            <input id="command-search" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Try: kubectl logs, disk usage, git rollback, DNS..." className="w-full rounded-xl border border-emerald-500/30 bg-slate-950 px-4 py-3 text-sm text-white outline-none placeholder:text-slate-500 focus:border-emerald-300"/>
            {search && <div className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
              {matches.map((item) => <Link key={item.href} href={item.href} className="rounded-lg border border-slate-700 bg-slate-900 p-3 hover:border-emerald-400/50"><span className="font-mono text-sm text-emerald-200">{item.name}</span><span className="mt-1 block text-xs text-slate-500">{item.category} / {item.subcategory}</span></Link>)}
              {matches.length === 0 && <p className="text-sm text-slate-400">No matching command topic. Try a tool name or command.</p>}
            </div>}
          </section>

          <section className="mb-8 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
            <div className="rounded-xl border border-slate-800 bg-slate-900/70 p-4"><p className="text-2xl font-black text-white">{categories.length}</p><p className="text-xs text-slate-400">Existing categories</p></div>
            <div className="rounded-xl border border-slate-800 bg-slate-900/70 p-4"><p className="text-2xl font-black text-white">{allTopics.length}</p><p className="text-xs text-slate-400">Existing command topics</p></div>
            <div className="rounded-xl border border-slate-800 bg-slate-900/70 p-4"><p className="text-2xl font-black text-white">{favorites.length}</p><p className="text-xs text-slate-400">Saved favourites</p></div>
            <div className="rounded-xl border border-slate-800 bg-slate-900/70 p-4"><p className="text-2xl font-black text-white">{history.length}</p><p className="text-xs text-slate-400">Recent commands</p></div>
          </section>

          {(favorites.length > 0 || history.length > 0) && <section className="mb-8 grid gap-4 lg:grid-cols-2">
            <div className="rounded-2xl border border-slate-800 bg-slate-900/60 p-5"><h2 className="font-bold text-white">★ Favourite commands</h2>{favorites.length ? <div className="mt-3 flex flex-wrap gap-2">{favorites.map((item) => <button key={item} onClick={() => setSearch(item)} className="rounded-lg border border-amber-500/20 bg-amber-500/5 px-3 py-2 font-mono text-xs text-amber-200">{item}</button>)}</div> : <p className="mt-2 text-xs text-slate-500">Save commands from their detail pages.</p>}</div>
            <div className="rounded-2xl border border-slate-800 bg-slate-900/60 p-5"><h2 className="font-bold text-white">Recent command activity</h2>{history.length ? <div className="mt-3 space-y-2">{history.slice(0,5).map((item) => <button key={item} onClick={() => setSimCommand(item)} className="block w-full truncate rounded-lg bg-slate-950 px-3 py-2 text-left font-mono text-xs text-slate-300">{item}</button>)}</div> : <p className="mt-2 text-xs text-slate-500">Copied and simulated commands appear here.</p>}</div>
          </section>}

          <div className="mb-4 flex items-end justify-between gap-3"><div><p className="font-mono text-xs uppercase tracking-widest text-emerald-300">Command catalog</p><h2 className="mt-1 text-xl font-bold text-white">Explore by technology</h2></div><span className="text-xs text-slate-500">Original navigation preserved</span></div>
          <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
            {categories.map((group,index) => {
              const count = group.subcategories.reduce((n,sub)=>n+sub.topics.length,0);
              return <Link key={group.name} href={`/command-explorer/${slug(group.name)}`} className="group rounded-2xl border border-emerald-500/20 bg-[#081711] p-5 transition hover:-translate-y-1 hover:border-emerald-400/50 hover:bg-[#0b2119]">
                <div className="mb-4 flex items-center justify-between"><span className="font-mono text-xs text-emerald-400">[{String(index+1).padStart(2,"0")}] COMMAND GROUP</span><span className="rounded-lg bg-emerald-400/10 px-3 py-2 text-xs text-emerald-200">{count} topics</span></div>
                <h3 className="font-mono text-lg font-bold text-emerald-100">{group.name}</h3><p className="mt-2 text-xs text-slate-400">{group.subcategories.length} command groups</p><p className="mt-5 text-sm font-semibold text-emerald-300">Open command group →</p>
              </Link>;
            })}
          </div>
          <footer className="mt-10 border-t border-slate-800 pt-5 text-xs text-slate-500">DevMavox · Command reference and safe practice workspace</footer>
        </div>
      </main>
    );
  }

  if (!selected || !profile) return <main className="min-h-screen bg-[#060d18] p-8 text-slate-200"><Link href="/command-explorer">← Back to Command Explorer</Link><p className="mt-5">Command topic not found.</p></main>;

  const favorite = favorites.includes(selected.name);
  return (
    <main className="min-h-screen bg-[#060d18] px-4 py-8 text-slate-100 sm:px-6 lg:px-8">
      <div className="mx-auto max-w-7xl">
        <div className="mb-6 flex flex-wrap items-center justify-between gap-3"><Link href="/command-explorer" className="text-sm text-slate-400 hover:text-white">← Command Explorer</Link><button onClick={()=>toggleFavorite(selected.name)} className={`rounded-full border px-3 py-2 text-xs ${favorite?"border-amber-400/40 bg-amber-400/10 text-amber-200":"border-slate-700 text-slate-300"}`}>{favorite?"★ Saved":"☆ Save command"}</button></div>
        <nav className="mb-5 flex flex-wrap gap-2 text-xs text-slate-500"><Link href="/command-explorer" className="hover:text-white">Explorer</Link><span>/</span><Link href={`/command-explorer/${slug(selected.category)}`} className="hover:text-white">{selected.category}</Link><span>/</span><Link href={`/command-explorer/${slug(selected.category)}/${slug(selected.subcategory)}`} className="hover:text-white">{selected.subcategory}</Link><span>/</span><span className="text-emerald-200">{selected.name}</span></nav>
        <header className="mb-6 rounded-3xl border border-emerald-500/25 bg-gradient-to-br from-[#0b211b] to-[#101a2a] p-6 sm:p-8"><p className="font-mono text-xs uppercase tracking-widest text-emerald-300">{selected.category} · {selected.subcategory}</p><h1 className="mt-2 font-mono text-3xl font-black text-white">{selected.name}</h1><p className="mt-3 max-w-3xl text-sm leading-7 text-slate-300">{profile.purpose}</p><p className="mt-3 text-xs text-slate-400">Practical command reference · options · examples · builder · verification</p></header>

        <section className="mb-5 rounded-2xl border border-emerald-500/25 bg-[#07140f] p-5">
          <div className="mb-3 flex items-center justify-between gap-3"><h2 className="font-mono text-sm font-bold text-emerald-200">01 / COMMAND BUILDER</h2><span className="text-xs text-slate-500">Build a command line</span></div>
          <p className="mb-4 text-sm text-slate-300">{profile.when}</p>
          <label className="mb-2 block text-xs text-slate-400">Arguments and target</label><input value={argument} onChange={(event)=>setArgument(event.target.value)} placeholder={profile.args || "No arguments required"} className="w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-3 font-mono text-sm text-white outline-none focus:border-emerald-400"/>
          {profile.flags.length>0 && <div className="mt-4 grid gap-2 sm:grid-cols-2">{profile.flags.map((item)=><label key={item.flag} className="flex cursor-pointer gap-2 rounded-lg border border-slate-800 bg-slate-950/60 p-3"><input type="checkbox" checked={selectedFlags.includes(item.flag)} onChange={(event)=>setSelectedFlags((old)=>event.target.checked?[...old,item.flag]:old.filter((v)=>v!==item.flag))} className="mt-1 accent-emerald-400"/><span><span className="font-mono text-xs text-emerald-200">{item.flag}</span><span className="mt-1 block text-xs text-slate-400">{item.meaning}</span></span></label>)}</div>}
          <div className="mt-4 rounded-xl border border-slate-700 bg-black p-4"><p className="mb-2 text-[10px] font-bold uppercase tracking-widest text-slate-500">Generated command</p><code className="block break-all font-mono text-sm text-emerald-300">$ {commandPreview}</code><div className="mt-3 flex flex-wrap gap-2"><button onClick={()=>copyCommand(commandPreview)} className="rounded-lg bg-emerald-400 px-4 py-2 text-xs font-bold text-slate-950">{copied?"Copied ✓":"Copy command"}</button><button onClick={()=>{setSimCommand(commandPreview);setSimOutput("");}} className="rounded-lg border border-slate-700 px-4 py-2 text-xs text-slate-200">Send to practice terminal</button><button onClick={()=>{setArgument(profile.args);setSelectedFlags([]);}} className="rounded-lg border border-slate-700 px-4 py-2 text-xs text-slate-300">Reset builder</button></div></div>
        </section>

        <section className="mb-5 rounded-2xl border border-slate-800 bg-slate-900/60 p-5"><h2 className="mb-3 font-mono text-sm font-bold text-emerald-200">02 / OPTIONS AND FLAGS</h2><div className="divide-y divide-slate-800">{profile.flags.map((item)=><div key={item.flag} className="grid gap-1 py-3 sm:grid-cols-[180px_1fr]"><code className="text-sm text-emerald-300">{item.flag}</code><p className="text-sm text-slate-300">{item.meaning}</p></div>)}</div></section>

        <section className="mb-5 rounded-2xl border border-slate-800 bg-slate-900/60 p-5"><h2 className="mb-4 font-mono text-sm font-bold text-emerald-200">03 / PRACTICAL EXAMPLES</h2><div className="space-y-3">{profile.examples.map((item)=><div key={item.command} className="rounded-xl border border-slate-800 bg-slate-950 p-4"><div className="mb-2 flex items-center justify-between gap-2"><span className="text-xs text-slate-400">{item.label}</span><button onClick={()=>copyCommand(item.command)} className="text-xs text-emerald-300 hover:text-white">Copy</button></div><code className="block break-all font-mono text-sm text-slate-200">$ {item.command}</code></div>)}</div></section>

        <section className="mb-5 grid gap-5 lg:grid-cols-2"><div className="rounded-2xl border border-slate-800 bg-slate-900/60 p-5"><h2 className="font-mono text-sm font-bold text-emerald-200">04 / EXPECTED OUTPUT</h2><pre className="mt-3 overflow-x-auto rounded-xl bg-black p-4 text-xs leading-6 text-emerald-300">{profile.output}</pre><p className="mt-2 text-[11px] text-slate-500">Illustrative output; exact text varies by OS, tool version and environment.</p></div><div className="rounded-2xl border border-slate-800 bg-slate-900/60 p-5"><h2 className="font-mono text-sm font-bold text-emerald-200">05 / NEXT DIAGNOSTIC COMMANDS</h2><div className="mt-3 space-y-2">{profile.next.map((item)=><div key={item} className="flex items-center justify-between gap-2 rounded-lg bg-slate-950 p-3"><code className="break-all text-xs text-slate-200">{item}</code><button onClick={()=>copyCommand(item)} className="shrink-0 text-xs text-emerald-300">Copy</button></div>)}</div></div></section>

        <section className="mb-5 rounded-2xl border border-cyan-500/20 bg-cyan-950/10 p-5"><h2 className="font-mono text-sm font-bold text-cyan-200">06 / HANDS-ON TASK</h2><p className="mt-3 text-sm leading-7 text-slate-200">{profile.task}</p><div className="mt-4 rounded-lg border border-cyan-500/20 bg-slate-950/70 p-4"><p className="text-xs font-bold uppercase tracking-wider text-cyan-300">Verification checklist</p><p className="mt-2 text-sm text-slate-300">{profile.verify}</p></div></section>

        <section className="mb-5 rounded-2xl border border-emerald-500/20 bg-[#07140f] p-5"><h2 className="font-mono text-sm font-bold text-emerald-200">07 / SAFE PRACTICE TERMINAL</h2><p className="mt-2 text-xs leading-5 text-slate-400">This is a simulator with predefined sample responses, not a real shell. It does not execute commands on your computer, server, AWS account or Kubernetes cluster.</p><div className="mt-4 flex flex-col gap-2 sm:flex-row"><input value={simCommand} onChange={(event)=>setSimCommand(event.target.value)} placeholder="Try: kubectl get pods -n production" className="min-w-0 flex-1 rounded-lg border border-slate-700 bg-black px-3 py-3 font-mono text-xs text-white outline-none focus:border-emerald-400"/><button onClick={runSimulation} className="rounded-lg bg-emerald-400 px-5 py-3 text-xs font-bold text-slate-950">Run simulation</button></div>{simOutput&&<pre className="mt-3 overflow-x-auto rounded-xl border border-slate-800 bg-black p-4 text-xs leading-6 text-emerald-300">{simOutput}</pre>}</section>

        <div className="flex flex-wrap justify-between gap-3 border-t border-slate-800 pt-5"><Link href={`/command-explorer/${slug(selected.category)}`} className="text-sm text-slate-400 hover:text-white">← Back to {selected.category}</Link><Link href="/command-explorer" className="text-sm font-semibold text-emerald-300 hover:text-white">Explore more commands →</Link></div>
      </div>
    </main>
  );
}
